from collections import Counter


def transform(grid):
    """Highlight missing or extra right-edge pixels in repeated row patterns."""
    out = [row[:] for row in grid]
    flat = [value for row in grid for value in row]
    if not flat:
        return out

    background = Counter(flat).most_common(1)[0][0]
    non_background = [value for value in flat if value != background]
    if not non_background:
        return out
    color = Counter(non_background).most_common(1)[0][0]
    height, width = len(grid), len(grid[0])

    # Fully colored rows act as complete reference lines. Other colored rows
    # are grouped into repeated multi-row patterns separated by background.
    full_rows = [r for r, row in enumerate(grid)
                 if all(value == color for value in row)]
    partial_rows = [r for r, row in enumerate(grid)
                    if any(value == color for value in row)
                    and not all(value == color for value in row)]
    groups = []
    for r in partial_rows:
        if not groups or r > groups[-1][-1] + 1:
            groups.append([r])
        else:
            groups[-1].append(r)

    # Align two repeated multi-row patterns by their horizontal translation.
    if len(groups) == 2 and len(groups[0]) == len(groups[1]) and len(groups[0]) > 1:
        first, second = groups
        best = None
        for shift in range(-width + 1, width):
            intersection = union = 0
            for ra, rb in zip(first, second):
                for c in range(width):
                    a_is_color = grid[ra][c] == color
                    d = c + shift
                    b_is_color = 0 <= d < width and grid[rb][d] == color
                    intersection += int(a_is_color and b_is_color)
                    union += int(a_is_color or b_is_color)
            score = (intersection / union if union else 0,
                     intersection, -abs(shift), shift)
            if best is None or score > best:
                best = score

        shift = best[3]
        if shift >= 0:
            source_rows, target_rows, delta = first, second, shift
        else:
            source_rows, target_rows, delta = second, first, -shift

        for source_r, target_r in zip(source_rows, target_rows):
            expected = [False] * width
            for c, value in enumerate(grid[source_r]):
                if value == color and 0 <= c + delta < width:
                    expected[c + delta] = True

            last_target = max(
                (c for c, value in enumerate(grid[target_r]) if value == color),
                default=-1)
            last_expected = max((c for c, value in enumerate(expected) if value),
                                default=-1)

            # Mark missing color in the target's trailing region.
            for c in range(last_target + 1, width):
                if expected[c] and grid[target_r][c] == background:
                    out[target_r][c] = 1

            # A detached extra colored tail is also marked as an anomaly.
            if last_target > last_expected:
                last_shared = max(
                    (c for c in range(width)
                     if expected[c] and grid[target_r][c] == color),
                    default=-1)
                if any(grid[target_r][c] == background
                       for c in range(last_shared + 1, last_target + 1)):
                    for c in range(last_shared + 1, last_target + 1):
                        if grid[target_r][c] == color and not expected[c]:
                            out[target_r][c] = 1
        return out

    # For isolated line examples, a complete row supplies the right-edge
    # continuation for any partial row of the same color.
    for r in partial_rows:
        last = max((c for c, value in enumerate(grid[r]) if value == color),
                   default=-1)
        for c in range(last + 1, width):
            if any(grid[rr][c] == color for rr in full_rows):
                out[r][c] = 1
    return out
